import json

def write_report(root,manifest,assessment,importance):
    a=assessment;m=a['test_performance'];c=manifest['config'];spy=a['benchmarks'][c['benchmark']]
    lines=[f'# Quant research report — {a["run"]}', '', '## MODEL',f'Selected: **{a["model"]}**, by validation-only costed Sharpe. No test tuning.',f'Configuration: {json.dumps(c,sort_keys=True)}',f'Hyperparameters: {json.dumps(manifest["hyperparameters"],sort_keys=True)}','', '## SIGNALS',importance.head(12).to_string(index=False),'','Permutation importance is post-hoc held-out diagnostic; correlated features and serial dependence complicate interpretation. Never used to reselect this model.','', '## PREDICTIONS','Run analyze.py or screen.py for current causal predictions. See current_predictions.csv after running those commands. Probability is an uncalibrated model estimate, not confidence of profit.','', '## BACKTEST',f'Test interval: {m["start"]} to {m["end"]}. Return {m["total_return"]:.2%}, CAGR {m["cagr"]:.2%}; {m["number_of_trades"]} orders after {m["costs"]:.2f} estimated costs.',json.dumps(m,indent=2),'','## BENCHMARK',f'{c["benchmark"]}: {spy["total_return"]:.2%} total return. Strategy difference: {m["total_return"]-spy["total_return"]:+.2%}. Same execution dates and cost assumptions; all individual buy-and-hold comparisons are in benchmarks.csv.','', '## RISK',f'Volatility {m["volatility"]:.2%}; maximum drawdown {m["max_drawdown"]:.2%}; exposure {m["exposure"]:.2%}. Sharpe/Sortino use zero risk-free rate.', '', '## MODEL EVALUATION',json.dumps(a['prediction_metrics'],indent=2),'','## ROBUSTNESS','Annual slices:',json.dumps(a['annual'],indent=2),'Signal-time SPY regime slices:',json.dumps(a['regimes'],indent=2),'Cost sensitivity (diagnostic only; not optimized):',json.dumps(a['cost_sensitivity_bps'],indent=2),'','## LIMITATIONS','- Selected current liquid-stock universe has survivorship/selection bias. No historical index membership or delisted-security dataset.','- Yahoo is not point-in-time institutional data. Adjusted OHLC contains retroactive split/dividend adjustments; simulated adjusted shares are research units, not actual historical executable quotes. No separate dividend cash credit.','- Fixed proportional commissions/slippage omit spreads varying by date, impact, taxes, liquidity constraints and borrow; no leverage/shorts/order execution.','- Daily close features can execute only at next open. Targets are next-open to horizon-open returns, NOT same-close executable returns.','- Training labels are purged by their realized end date, including all fold boundaries. Cross-sectional samples share dates; no randomized temporal splits.','- Overlapping targets are dependent; no naive confidence intervals or accuracy-only profitability claim. Small universe/limited regimes and many attempted models increase selection risk.','- RF/boosting probabilities are not automatically calibrated. Inspect calibration.png and Brier scores; confidence is not quantified.','- Missing held-asset prices halt evaluation instead of inventing liquidation prices; missing new-entry opens never fill. No delisting treatment means unsupported missing-delisting cases are a blocker.','- Win rate/profit factor use closed weighted-average-cost partial lots; number of trades counts orders, turnover is one-way gross notional/NAV summed over executions.','- Final-period diagnostics must not be fed back into model selection. The audit is local and cannot prevent a researcher from changing files or repeated research choices.',f'- Independent untouched assessment flag: {a["holdout_independence"]}. Repeated protocol runs after viewing test results are exploratory, not new evidence.','', '## ARTIFACTS','research.png, calibration.png, equity.csv, trades.csv, test_predictions.csv, model_comparison.csv, feature_importance.csv, permutation_importance.csv, assessment.json, test_folds.json.']
    current=root/'current_predictions.csv'
    if current.exists():
        import pandas as pd
        lines += ['', '## CURRENT MODEL ESTIMATES (latest separate refit)', pd.read_csv(current)[['ticker','date','predicted_return','probability','signal']].to_string(index=False)]
    if (root/'DATA_REVISION_NOTE.md').exists():
        lines += ['', '## REPRODUCIBILITY CAVEAT', (root/'DATA_REVISION_NOTE.md').read_text()]
    (root/'report.md').write_text('\n'.join(lines))
